const passos = $input.first().json;
const chamadas = new Set((passos.intermediateSteps || []).map(p => p.action?.tool));
if (!chamadas.has('Consultar_ponto') || !chamadas.has('Consultar_procedimentos')) throw new Error('Consultas obrigatórias ausentes');
const raw = String(passos.output).trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');
const resultado = JSON.parse(raw);
const fontes = $('Leitura do painel').first().json.body.fontes;
if (!fontes.some(f => f.codigo === resultado.fonte) || typeof resultado.texto !== 'string' || !resultado.texto.trim() || resultado.texto.length > 900) throw new Error('Fonte ou orientação inválida');
return [{json:{texto:resultado.texto.trim(),fonte:resultado.fonte}}];
